-- COMMAND ----------

-- Export all tables to Volume as CSV
BEGIN
  IF NOT data_exists THEN
    EXECUTE IMMEDIATE
  CONCAT(
    'INSERT OVERWRITE DIRECTORY ', CHAR(39), '/Volumes/', catalog_name, '/data/course_data/raw_customers', CHAR(39), ' ',
    'USING CSV OPTIONS (', CHAR(39), 'header', CHAR(39), ' ', CHAR(39), 'true', CHAR(39), ') ',
    'SELECT * FROM ', catalog_name, '.', schema_name, '.raw_customers'
  );
    EXECUTE IMMEDIATE
  CONCAT(
    'INSERT OVERWRITE DIRECTORY ', CHAR(39), '/Volumes/', catalog_name, '/data/course_data/raw_products', CHAR(39), ' ',
    'USING CSV OPTIONS (', CHAR(39), 'header', CHAR(39), ' ', CHAR(39), 'true', CHAR(39), ') ',
    'SELECT * FROM ', catalog_name, '.', schema_name, '.raw_products'
  );
    EXECUTE IMMEDIATE
  CONCAT(
    'INSERT OVERWRITE DIRECTORY ', CHAR(39), '/Volumes/', catalog_name, '/data/course_data/raw_orders', CHAR(39), ' ',
    'USING CSV OPTIONS (', CHAR(39), 'header', CHAR(39), ' ', CHAR(39), 'true', CHAR(39), ') ',
    'SELECT * FROM ', catalog_name, '.', schema_name, '.raw_orders'
  );
    EXECUTE IMMEDIATE
  CONCAT(
    'INSERT OVERWRITE DIRECTORY ', CHAR(39), '/Volumes/', catalog_name, '/data/course_data/raw_orders_new_batch', CHAR(39), ' ',
    'USING CSV OPTIONS (', CHAR(39), 'header', CHAR(39), ' ', CHAR(39), 'true', CHAR(39), ') ',
    'SELECT * FROM ', catalog_name, '.', schema_name, '.raw_orders_new_batch'
  );
    EXECUTE IMMEDIATE
  CONCAT(
    'INSERT OVERWRITE DIRECTORY ', CHAR(39), '/Volumes/', catalog_name, '/data/course_data/raw_customers_cdc/initial', CHAR(39), ' ',
    'USING CSV OPTIONS (', CHAR(39), 'header', CHAR(39), ' ', CHAR(39), 'true', CHAR(39), ') ',
    'SELECT * FROM ', catalog_name, '.', schema_name, '.raw_customers_cdc'
  );
    EXECUTE IMMEDIATE
  CONCAT(
    'INSERT OVERWRITE DIRECTORY ', CHAR(39), '/Volumes/', catalog_name, '/data/course_data/raw_customers_cdc/new_batch', CHAR(39), ' ',
    'USING CSV OPTIONS (', CHAR(39), 'header', CHAR(39), ' ', CHAR(39), 'true', CHAR(39), ') ',
    'SELECT * FROM ', catalog_name, '.', schema_name, '.raw_customers_cdc_new_batch'
  );
    EXECUTE IMMEDIATE
  CONCAT(
    'INSERT OVERWRITE DIRECTORY ', CHAR(39), '/Volumes/', catalog_name, '/data/course_data/customer_feedback', CHAR(39), ' ',
    'USING CSV OPTIONS (', CHAR(39), 'header', CHAR(39), ' ', CHAR(39), 'true', CHAR(39), ') ',
    'SELECT * FROM ', catalog_name, '.', schema_name, '.customer_feedback'
  );
  END IF;
END;

-- COMMAND ----------

SELECT 'raw_customers' AS table_name, COUNT(*) AS rows FROM IDENTIFIER(catalog_name || '.' || schema_name || '.raw_customers')
  UNION ALL
SELECT 'raw_products', COUNT(*) FROM IDENTIFIER(catalog_name || '.' || schema_name || '.raw_products')
  UNION ALL
SELECT 'raw_orders', COUNT(*) FROM IDENTIFIER(catalog_name || '.' || schema_name || '.raw_orders')
  UNION ALL
SELECT 'raw_orders_new_batch', COUNT(*) FROM IDENTIFIER(catalog_name || '.' || schema_name || '.raw_orders_new_batch')
  UNION ALL
SELECT 'raw_customers_cdc', COUNT(*) FROM IDENTIFIER(catalog_name || '.' || schema_name || '.raw_customers_cdc')
  UNION ALL
SELECT 'raw_customers_cdc_new_batch', COUNT(*) FROM IDENTIFIER(catalog_name || '.' || schema_name || '.raw_customers_cdc_new_batch')
  UNION ALL
SELECT 'customer_feedback', COUNT(*) FROM IDENTIFIER(catalog_name || '.' || schema_name || '.customer_feedback')
  ORDER BY table_name;
